        having: Optional['types.document_embeddingsScalarWhereWithAggregatesInput'] = None,
        count: Optional[Union[bool, 'types.document_embeddingsCountAggregateInput']] = None,
        order: Optional[Union[Mapping['types.document_embeddingsScalarFieldKeys', 'types.SortOrder'], List[Mapping['types.document_embeddingsScalarFieldKeys', 'types.SortOrder']]]] = None,
